INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0510', '正反対な君と僕', '2026年冬', 'PR0079', 'TVシリーズ', 12, '『正反対な君と僕』（せいはんたいなきみとぼく）は、阿賀沢紅茶による日本の漫画作品。『少年ジャンプ+』（集英社）にて、2021年1月7日掲載の第一話となる読切版を経て、2022年5月2日から2024年11月25日まで連載された。 性格が正反対なカップルと、その友人たちをとおして高校生活を描いたラブコメ作品である。 単行本は全8巻。2026年5月時点で電子版を含む累計発行部数は210万部を突破している', 184951) ON CONFLICT DO NOTHING;
