INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0581', 'ニワトリ・ファイター', '2026年春', 'PR0126', 'TVシリーズ', 12, '『ニワトリ・ファイター』は、桜谷シュウによる日本の漫画。『コミプレ-Comiplex-』→『HERO''S Web』（ヒーローズ）で、2020年12月18日から連載されている。日本国外でのタイトルは『Rooster Fighter』。日本を舞台に、ニワトリが異形の巨大な生物である鬼獣と戦い、人類を救っていくストーリー。 メディアミックスとして、日本では2026年4月からテレビアニメが放送中。', 179813) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0582', 'よわよわ先生', '2026年春', 'PR0048', 'TVシリーズ', 12, '『よわよわ先生』（よわよわせんせい）は、福地カミオによる日本の漫画。『週刊少年マガジン』（講談社）にて、2022年51号（11月16日発売）から連載中。 メディアミックスとして、2026年4月よりテレビアニメが放送中。', 185211) ON CONFLICT DO NOTHING;
