INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0645', '天は赤い河のほとり', '2026年夏', 'PR0131', 'TVシリーズ', NULL, '『天は赤い河のほとり』（そらはあかいかわのほとり）は、篠原千絵による日本の漫画作品。 古代オリエントを舞台にした物語で、タイトルの「赤い河」はトルコを流れるクズルウルマク川を指す。', 207809) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0646', '花織さんは転生しても喧嘩がしたい', '2026年夏', 'PR0058', 'TVシリーズ', NULL, '『花織さんは転生しても喧嘩がしたい』（はなおりさんはてんせいしてもけんかがしたい）は、氷川へきるによる日本の漫画作品。『モーニング・ツー』（講談社）にて2021年10号（8月23日発売）から休刊号となる2022年11号（9月26日発売）まで連載され、その後も引き続き同名Webサイトにて連載中。 メディアミックスとして、2026年よりテレビアニメが放送予定。', 199066) ON CONFLICT DO NOTHING;
