INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH001926', 'AN0505', '虎杖悠仁', '虎杖 悠仁（いたどり ゆうじ）は、芥見下々による日本の漫画『呪術廻戦』に登場する架空の人物（主人公）。並外れた身体能力を備えた少年である悠仁は、特級呪物・両面宿儺の指を食べたことがきっかけで、呪術の世界に足を踏み入れる。悠仁は『NARUTO -ナルト-』の主人公・うずまきナルトや『BLEACH』の主人公・黒崎一護の影響を受けて制作された。アニメ版では榎木淳弥が声優を務めた。多くの評論家が悠仁の成長', 15, '男性', 127212) ON CONFLICT DO NOTHING;
