INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH001931', 'AN0506', 'フリーレン', 'フリーレン（Frieren）は、山田鐘人（原作）とアベツカサ（作画）による日本の漫画『葬送のフリーレン』の登場人物（主人公）。 フリーレンはエルフの魔法使いであり、勇者ヒンメルが率いるパーティの一員として、10年間の冒険の末に魔王を倒した。フリーレンは50年後にパーティのメンバーと再会するが、ヒンメルは間もなく死亡し、フリーレンはヒンメルについてもっと知ろうとしなかったことを後悔する。大陸の北部に', 1000, '女性', 176754) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH001932', 'AN0506', 'フェルン', 'フェルン（ドイツ語: Fern）は山田鐘人（原作）とアベツカサ（作画）による日本の漫画『葬送のフリーレン』の登場人物。', NULL, '女性', 183965) ON CONFLICT DO NOTHING;
