INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH002034', 'AN0527', '黒蜥蜴', '『黒蜥蜴』（くろとかげ）は、江戸川乱歩の長編探偵小説。および、作中に登場する女性盗賊の通称。小説は月刊誌『日の出』（新潮社）で1934年（昭和9年）1月号から12月号まで連載された。いわゆる乱歩の通俗連載長篇の一つで、宝石など「美しいもの」を狙う美貌の女賊・黒蜥蜴と名探偵・明智小五郎が対決する。端々に乱歩が本分としている「エロ・グロ」の趣向がこらされている。', NULL, '女性', 382468) ON CONFLICT DO NOTHING;
