INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH002575', 'AN0645', 'キックリ', 'キックリ（Kikkuli）は紀元前15世紀ごろのヒッタイトで戦闘用馬車を曳く馬匹を訓練していた人物。ミタンニの生まれ。1906年に土中から発見されたキックリ文書という粘土板にその名が記されている（#文書の発見とその内容）。文書に記された訓練の内容は現代の科学的な観点から見ても理に適ったものである（#馬匹訓練の再現実験）。', NULL, '男性', 35934) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH002576', 'AN0645', '氷室', '氷室（ひむろ、ひょうしつ、英語：ice house アイスハウス）とは、天然の氷や雪を蓄えることで冷温貯蔵庫として機能する施設のこと。 古代より世界各地で利用されてきた蓄熱施設である。洞窟や横穴を利用したもの、井戸状の穴を利用したもの、石積みやドーム状の建築物など古代以来の土木技術による建造物のほか、現代的技術で建設された建造物まで、様々な様式がある。 もともと冷蔵庫として一般的な形式であり、20', NULL, '男性', 393359) ON CONFLICT DO NOTHING;
