INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH002660', 'AN0663', '主人公', '主人公（しゅじんこう）は、フィクション作品（小説・映画・ドラマ・漫画・アニメ・ゲームなど）のストーリーの中心となり、物語を牽引していく登場人物。 日本語の「主人公」という語句は、坪内逍遥によるものとされている。また、主人公の役割を演じる者は主役と呼ばれている。英語ではヒーローやヒロインと同義である場合もあるが、形式張った表現ではプロタゴニスト (Protagonist) という。また、作品名となっ', NULL, '男性', 377067) ON CONFLICT DO NOTHING;
