INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH002713', 'AN0680', '校長', '校長（こうちょう、米: principal、英: head teacher、大学の場合はchancellor、president、provostなどとも）は、学校などの教育機関・教育施設に置かれる最上位の教職員。学校長とも呼ばれるが、学校教育法上の正式な名称ではない。', NULL, NULL, 367536) ON CONFLICT DO NOTHING;
