INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH002716', 'AN0681', '孫悟天', '孫 悟天（そん ごてん）は、鳥山明の漫画『ドラゴンボール』およびそれを原作とするアニメ『ドラゴンボールZ』『ドラゴンボールGT』『ドラゴンボール改』『ドラゴンボール超』に登場する架空のキャラクター。 アニメでの声優は野沢雅子。 原作では其之四百二十四「ビーデル緊急出動!!」、アニメでは『ドラゴンボールZ』第201話「愛と正義のグレートサイヤマン参上」、『ドラゴンボール改』第99話「あれから7年!', NULL, '男性', 2551) ON CONFLICT DO NOTHING;
